package org.jfree.chart.renderer;

import java.awt.Color;
import java.awt.Paint;
import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import org.jfree.chart.util.PublicCloneable;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;

public class GrayPaintScale_getPaint_TriageGen1Test {

    @Test
    public void testGetPaint_WithinBounds() {
        double lower = 0.0;
        double upper = 100.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // Midpoint: (50-0)/(100-0) * 255 = 127.5 -> cast to int is 127
        Paint paint = scale.getPaint(50.0);
        assertNotNull(paint);
        assertEquals(new Color(127, 127, 127), paint);
    }










}

