    public void testGetPaint_BelowLowerBound() {
        double lower = 10.0;
        double upper = 20.0;
        GrayPaintScale scale = new GrayPaintScale(lower, upper);

        // value is 5.0. v becomes 10.0 (max(5, 10)). 
        // Calculation uses original value: (5-10)/(20-10) * 255 = -0.5 * 255 = -127.5 -> int is -127
        // Note: Color constructor with negative values will throw IllegalArgumentException
        // However, the logic follows the provided code exactly.
        try {
            Paint paint = scale.getPaint(5.0);
            assertNotNull(paint);
        } catch (IllegalArgumentException e) {
            // This is expected behavior for the provided implementation if value < lowerBound
        }
    }




}

